<script>
  import {onMount,onDestroy} from 'svelte';import {client,createLoader,demoPath,date,fmt} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';
  export let table;export let lang='vi';const resource=createLoader();let wrong=false;
  $: t=(vi,en)=>lang==='en'?en:vi;
  function load(){return resource.load(signal=>client.request(`${demoPath(table.slug)}/logs?limit=100&wrong_only=${wrong}`,{signal}));}
  onMount(load);onDestroy(resource.dispose);
</script>
<section class="panel"><div class="flex flex-wrap justify-between items-center gap-4 mb-6"><h2>{t('Hoạt động tìm kiếm gần đây','Recent search activity')}</h2><div class="flex gap-4 items-center"><label class="flex gap-2 items-center text-xs"><input type="checkbox" bind:checked={wrong} on:change={load}/>{t('Chỉ phản hồi sai','Incorrect feedback only')}</label><Button busy={$resource.loading} on:click={load}><Icon name="refresh" size={16}/>{t('Tải lại','Reload')}</Button></div></div><Notice error={$resource.error} retry={load} {lang}/>
  <div aria-busy={$resource.loading}>{#if !$resource.data&&$resource.loading}<div class="empty" role="status">{t('Đang tải nhật ký…','Loading logs…')}</div>{:else if $resource.data?.length}<div class="table-scroll"><table class="data-table"><thead><tr>{#each [t('Thời gian','Time'),t('Câu hỏi','Question'),t('Kết quả','Result'),t('ID dòng','Row IDs'),'ms',t('Phản hồi','Feedback')] as h}<th>{h}</th>{/each}</tr></thead><tbody>{#each $resource.data as row (row.request_id)}<tr><td class="whitespace-nowrap text-muted">{date(row.created_at)}</td><td>{row.text}</td><td><span class="badge" class:ok={row.status==='matched'}>{row.status}</span>{#if row.cache_hit}<span class="text-xs text-muted"> cache</span>{/if}</td><td>{(row.product_ids||[]).join(', ')}</td><td>{fmt(Math.round(row.latency?.total||0))}</td><td>{row.feedback?(row.feedback.correct?t('Đúng','Correct'):t('Chưa đúng','Incorrect')):'—'}</td></tr>{/each}</tbody></table></div>{:else if !$resource.error}<div class="empty"><h2>{t('Chưa có nhật ký','No logs yet')}</h2><p>{t('Nhật ký sẽ xuất hiện sau khi tìm kiếm.','Search activity will appear here.')}</p></div>{/if}</div>
</section>
